import React, { useState, useEffect } from 'react';
import './CustomerList.css';

const CustomerList = () => {
  const [customers, setCustomers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [showModal, setShowModal] = useState(false);
  const [selectedCustomer, setSelectedCustomer] = useState(null);

  // Fetch customers from backend
  useEffect(() => {
    fetchCustomers();
  }, []);

  const fetchCustomers = async () => {
    try {
      setLoading(true);
      const response = await fetch('http://localhost:8080/api/customers');
      if (!response.ok) {
        throw new Error('Failed to fetch customers');
      }
      const data = await response.json();
      setCustomers(data);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (customerId) => {
    if (window.confirm('Are you sure you want to delete this customer?')) {
      try {
        const response = await fetch(`http://localhost:8080/api/customers/${customerId}`, {
          method: 'DELETE',
        });
        
        if (response.ok) {
          setCustomers(customers.filter(customer => customer.id !== customerId));
          alert('Customer deleted successfully!');
        } else {
          throw new Error('Failed to delete customer');
        }
      } catch (err) {
        alert('Error deleting customer: ' + err.message);
      }
    }
  };

  const handleViewDetails = (customer) => {
    setSelectedCustomer(customer);
    setShowModal(true);
  };

  const closeModal = () => {
    setShowModal(false);
    setSelectedCustomer(null);
  };

  if (loading) {
    return (
      <div className="customers-container">
        <div className="loading-spinner">
          <div className="spinner"></div>
          <p>Loading customers...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="customers-container">
        <div className="error-message">
          <h3>Error loading customers</h3>
          <p>{error}</p>
          <button onClick={fetchCustomers} className="retry-btn">
            Try Again
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="customers-container">
      <div className="customers-header">
        <h1>Customer Management</h1>
        <div className="header-actions">
          <button onClick={fetchCustomers} className="refresh-btn">
            🔄 Refresh
          </button>
          <span className="customer-count">
            Total: {customers.length} customers
          </span>
        </div>
      </div>

      {customers.length === 0 ? (
        <div className="no-customers">
          <h3>No customers found</h3>
          <p>Start by registering your first customer!</p>
        </div>
      ) : (
        <div className="customers-table-container">
          <table className="customers-table">
            <thead>
              <tr>
                <th>ID</th>
                <th>Name</th>
                <th>Email</th>
                <th>Phone</th>
                <th>Type</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {customers.map((customer) => (
                <tr key={customer.id} className="customer-row">
                  <td className="customer-id">{customer.id}</td>
                  <td className="customer-name">
                    {customer.firstName} {customer.lastName}
                  </td>
                  <td className="customer-email">{customer.email}</td>
                  <td className="customer-phone">{customer.phoneNumber}</td>
                  <td>
                    <span className={`customer-type ${customer.customerType?.toLowerCase()}`}>
                      {customer.customerType || 'REGULAR'}
                    </span>
                  </td>
                  <td className="customer-actions">
                    <button
                      onClick={() => handleViewDetails(customer)}
                      className="btn btn-view"
                      title="View Details"
                    >
                      👁️ View
                    </button>
                    <button
                      onClick={() => handleDelete(customer.id)}
                      className="btn btn-delete"
                      title="Delete Customer"
                    >
                      🗑️ Delete
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* Customer Details Modal */}
      {showModal && selectedCustomer && (
        <div className="modal-overlay" onClick={closeModal}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Customer Details</h2>
              <button onClick={closeModal} className="close-btn">×</button>
            </div>
            <div className="modal-body">
              <div className="customer-details">
                <div className="detail-row">
                  <label>ID:</label>
                  <span>{selectedCustomer.id}</span>
                </div>
                <div className="detail-row">
                  <label>First Name:</label>
                  <span>{selectedCustomer.firstName}</span>
                </div>
                <div className="detail-row">
                  <label>Last Name:</label>
                  <span>{selectedCustomer.lastName}</span>
                </div>
                <div className="detail-row">
                  <label>Email:</label>
                  <span>{selectedCustomer.email}</span>
                </div>
                <div className="detail-row">
                  <label>Phone:</label>
                  <span>{selectedCustomer.phoneNumber}</span>
                </div>
                <div className="detail-row">
                  <label>Type:</label>
                  <span className={`customer-type ${selectedCustomer.customerType?.toLowerCase()}`}>
                    {selectedCustomer.customerType || 'REGULAR'}
                  </span>
                </div>
                {selectedCustomer.createdAt && (
                  <div className="detail-row">
                    <label>Created:</label>
                    <span>{new Date(selectedCustomer.createdAt).toLocaleString()}</span>
                  </div>
                )}
              </div>
            </div>
            <div className="modal-footer">
              <button onClick={closeModal} className="btn btn-secondary">
                Close
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CustomerList;
